const input = $json.body || $json.query || {};
const resumeText = input.resume || '';

const skillKeywords = [
  'python', 'java', 'javascript', 'react', 'node', 'angular', 'vue',
  'aws', 'azure', 'docker', 'kubernetes', 'sql', 'mongodb',
  'machine learning', 'ai', 'data science', 'analytics',
  'project management', 'agile', 'scrum', 'leadership'
];

const extractedSkills = skillKeywords.filter(skill =>
  resumeText.toLowerCase().includes(skill)
);

let experienceLevel = 'entry';
const yearsMatch = resumeText.match(/(\d+)\+?\s*years?/i);
if (yearsMatch) {
  const years = parseInt(yearsMatch[1]);
  if (years >= 7) experienceLevel = 'senior';
  else if (years >= 3) experienceLevel = 'mid';
}

return [{
  json: {
    job_title: input.job_title || extractedSkills[0] || 'developer',
    location: input.location || 'India',
    skills: extractedSkills,
    experience_level: experienceLevel,
    min_salary: input.min_salary || 0,
    max_salary: input.max_salary || 999999999,
    job_type: input.job_type || 'all',
    remote_option: input.remote_option || 'all',
    resume_text: resumeText,
    preferred_cities: input.cities || ['bangalore', 'mumbai', 'delhi', 'hyderabad', 'pune', 'chennai']
  }
}];

const jobsData = $input.first().json;
const params = $('Extract Resume & Parameters').first().json;
const jobs = jobsData.results || [];

const indiaLocations = {
  cities: [
    'mumbai', 'delhi', 'bangalore', 'bengaluru', 'hyderabad', 'ahmedabad',
    'chennai', 'kolkata', 'surat', 'pune', 'jaipur', 'lucknow', 'kanpur',
    'nagpur', 'indore', 'thane', 'bhopal', 'visakhapatnam', 'pimpri', 'patna',
    'vadodara', 'ghaziabad', 'ludhiana', 'agra', 'nashik', 'faridabad',
    'meerut', 'rajkot', 'kalyan', 'vasai', 'varanasi', 'srinagar', 'aurangabad',
    'dhanbad', 'amritsar', 'navi mumbai', 'allahabad', 'ranchi', 'howrah',
    'coimbatore', 'jabalpur', 'gwalior', 'vijayawada', 'jodhpur', 'madurai',
    'raipur', 'kota', 'chandigarh', 'gurgaon', 'gurugram', 'noida', 'goa',
    'kochi', 'cochin', 'mysore', 'thiruvananthapuram', 'trivandrum', 'bhubaneswar',
    'dehradun', 'jamshedpur', 'cuttack', 'tiruppur', 'salem', 'warangal'
  ],
  states: [
    'maharashtra', 'karnataka', 'tamil nadu', 'telangana', 'gujarat',
    'uttar pradesh', 'west bengal', 'rajasthan', 'madhya pradesh',
    'kerala', 'haryana', 'punjab', 'andhra pradesh', 'odisha', 'goa'
  ],
  country: ['india', 'bharath', 'bharat']
};

const indiaJobs = jobs.filter(job => {
  const location = ((job.location && job.location.display_name) || '').toLowerCase();
  const area = ((job.location && job.location.area) || []).map(a => a.toLowerCase());
  return (
    indiaLocations.cities.some(city => location.includes(city)) ||
    indiaLocations.states.some(state => location.includes(state)) ||
    indiaLocations.country.some(country => location.includes(country)) ||
    area.some(a => indiaLocations.cities.includes(a) || indiaLocations.states.includes(a))
  );
});

let filteredJobs = indiaJobs;
if (params.preferred_cities && params.preferred_cities.length > 0) {
  const preferredCitiesLower = params.preferred_cities.map(c => c.toLowerCase());
  const cityFilteredJobs = indiaJobs.filter(job => {
    const location = ((job.location && job.location.display_name) || '').toLowerCase();
    return preferredCitiesLower.some(city => location.includes(city));
  });
  if (cityFilteredJobs.length > 0) {
    filteredJobs = cityFilteredJobs;
  }
}

if (params.job_type && params.job_type !== 'all') {
  filteredJobs = filteredJobs.filter(job => {
    const title = (job.title || '').toLowerCase();
    const description = (job.description || '').toLowerCase();
    if (params.job_type === 'full-time') {
      return title.includes('full time') || title.includes('full-time') ||
             description.includes('full time') || description.includes('full-time');
    } else if (params.job_type === 'contract') {
      return title.includes('contract') || description.includes('contract');
    } else if (params.job_type === 'part-time') {
      return title.includes('part time') || title.includes('part-time');
    }
    return true;
  });
}

if (params.remote_option && params.remote_option !== 'all') {
  filteredJobs = filteredJobs.filter(job => {
    const description = (job.description || '').toLowerCase();
    if (params.remote_option === 'remote') {
      return description.includes('remote') || description.includes('work from home') || description.includes('wfh');
    } else if (params.remote_option === 'hybrid') {
      return description.includes('hybrid');
    } else if (params.remote_option === 'onsite') {
      return !description.includes('remote') && !description.includes('hybrid');
    }
    return true;
  });
}

filteredJobs = filteredJobs.filter(job => {
  const salaryMin = job.salary_min || 0;
  const salaryMax = job.salary_max || 999999999;
  return salaryMin >= params.min_salary &&
         (params.max_salary === 999999999 || salaryMax <= params.max_salary);
});

return [{ json: { filteredJobs, params } }];

const data = $input.first().json;
const jobs = data.filteredJobs;
const params = data.params;

function calculateMatchScore(job, resumeSkills, resumeText) {
  let score = 0;
  const title = (job.title || '').toLowerCase();
  const description = (job.description || '').toLowerCase();
  const fullText = title + ' ' + description;

  if (resumeSkills && resumeSkills.length > 0) {
    const matchedSkills = resumeSkills.filter(skill =>
      fullText.includes(skill.toLowerCase())
    );
    score += (matchedSkills.length / resumeSkills.length) * 40;
  }

  const resumeKeywords = resumeText.toLowerCase().split(/\W+/).filter(w => w.length > 3);
  const titleWords = title.split(/\W+/);
  const titleMatches = titleWords.filter(word => resumeKeywords.includes(word));
  score += (titleMatches.length / Math.max(titleWords.length, 1)) * 30;

  if (params.experience_level === 'senior' && (title.includes('senior') || title.includes('lead'))) {
    score += 20;
  } else if (params.experience_level === 'mid' && (title.includes('mid') || !title.includes('senior'))) {
    score += 20;
  } else if (params.experience_level === 'entry' && (title.includes('junior') || title.includes('entry'))) {
    score += 20;
  } else {
    score += 10;
  }

  const location = ((job.location && job.location.display_name) || '').toLowerCase();
  if (params.preferred_cities && params.preferred_cities.some(city =>
    location.includes(city.toLowerCase())
  )) {
    score += 10;
  }

  return Math.min(score, 100);
}

const scoredJobs = jobs.map(job => {
  const matchScore = calculateMatchScore(job, params.skills, params.resume_text);
  const salary = (job.salary_min && job.salary_max)
    ? '₹' + Math.round(job.salary_min).toLocaleString('en-IN') + ' - ₹' + Math.round(job.salary_max).toLocaleString('en-IN')
    : 'Not specified';
  return {
    title: job.title,
    company: (job.company && job.company.display_name) || 'Not specified',
    location: (job.location && job.location.display_name) || 'India',
    city: (job.location && job.location.area && job.location.area[0]) || 'Not specified',
    state: (job.location && job.location.area && job.location.area[1]) || 'Not specified',
    salary,
    salary_min: job.salary_min || 0,
    salary_max: job.salary_max || 0,
    description: (job.description || '').substring(0, 300) + '...',
    url: job.redirect_url,
    posted: job.created,
    match_score: Math.round(matchScore),
    category: (job.category && job.category.label) || 'General',
    contract_type: job.contract_type || 'Not specified'
  };
});

scoredJobs.sort((a, b) => b.match_score - a.match_score);

const jobsByCity = {};
scoredJobs.forEach(job => {
  const city = job.city;
  if (!jobsByCity[city]) jobsByCity[city] = [];
  jobsByCity[city].push(job);
});

return [{
  json: {
    total_jobs: scoredJobs.length,
    jobs: scoredJobs.slice(0, 20),
    jobs_by_city: jobsByCity,
    filters_applied: {
      location: params.location,
      preferred_cities: params.preferred_cities,
      min_salary: params.min_salary,
      max_salary: params.max_salary !== 999999999 ? params.max_salary : 'No limit',
      job_type: params.job_type,
      remote_option: params.remote_option,
      experience_level: params.experience_level
    },
    matched_skills: params.skills
  }
}];
